[{"tool": "search_knowledge_base", "result": {"success": true, "data": [{"text": "Im normalen Grand Prix erhalten die bestplatzierten Fahrer Punkte nach dem offiziellen Punkteschema. Sprint-Wochenenden haben ein zusätzliches Sprint-Rennen mit eigener Punktevergabe.", "metadata": {"source": "local-curated", "data_type": "background_knowledge", "document_id": "concept-points"}, "distance": 0.32788389921188354}, {"text": "Ein Sprint ist ein kürzeres Rennen innerhalb ausgewählter Formel-1-Wochenenden. Er ergänzt den Grand Prix und kann eigene Meisterschaftspunkte vergeben.", "metadata": {"document_id": "concept-sprint", "source": "local-curated", "data_type": "background_knowledge"}, "distance": 0.4339263439178467}, {"text": "Das Qualifying bestimmt die Startaufstellung. In drei Abschnitten scheiden Fahrer aus; die schnellste Runde entscheidet die jeweilige Position.", "metadata": {"source": "local-curated", "document_id": "concept-qualifying", "data_type": "background_knowledge"}, "distance": 0.4352915287017822}, {"text": "Die Fahrerwertung zählt die Punkte einzelner Fahrer. Die Konstrukteurswertung zählt die Punkte der beiden Fahrer eines Teams zusammen.", "metadata": {"data_type": "background_knowledge", "source": "local-curated", "document_id": "concept-standings"}, "distance": 0.5089516639709473}, {"text": "{
